-- 000015 down: roll back report customization.
--
-- Drops in reverse order of up.sql so FK cascade paths unwind
-- cleanly. Loses all report_ratings + preference_suggestions_log
-- rows AND wipes report_preferences from every user. Style data
-- is not PHI and is regenerated by user action; safe to lose.

DROP INDEX IF EXISTS idx_pref_sugg_log_therapist;
DROP TABLE IF EXISTS preference_suggestions_log;

DROP INDEX IF EXISTS idx_report_ratings_negative;
DROP INDEX IF EXISTS idx_report_ratings_therapist;
DROP TABLE IF EXISTS report_ratings;

ALTER TABLE users
    DROP COLUMN IF EXISTS report_preferences;
